dtsPropsFor.Slider:
value: number;
onValueChange: (value: number) => void;
min?: number;
max: number;
step?: number;
/** Names the control for a screen reader — there is no visible <label>. */
label: string;
/** What this stop *is*, spoken instead of the bare number ("v3.10, 21 June"). */
valueText: string;
/** One tick per stop. Passed through so the ticks can not drift off the range. */
ticks?: boolean;

dtsPropsFor.Pager:
/** 1-indexed. */
page: number;
pageCount: number;
onPage: (page: number) => void;
/** aria-label on the <nav>. */
label?: string;

dtsPropsFor.NextCards:
/** Already chosen by the caller — this component picks nothing, which is
 *  what makes it safe under prerender + hydration. Renders null when empty. */
cards: readonly {
  /** Router path. Also the de-dupe key and what the card prints as its slug. */
  to: string;
  /** The small label over the title — the nav group for this page. */
  group: string;
  /** Short title. */
  label: string;
  /** One line. Sentence case, ends with a period. Clamped to 4 lines. */
  blurb: string;
}[];
/** The visible <h2>. */
heading?: string;
/** aria-label on the <nav>, for a screen reader landmark list. */
label?: string;

dtsPropsFor.Footer:
/** The closing statement. Each page ends on its own sentence. */
line: string;
/** The trotting horse beside the line. Home and the 404. */
horse?: boolean;
